/**
 * lib/engines/core/v4/adapter.macro.v4.ts
 * ═══════════════════════════════════════════════════════════════════════════════
 *  V4.0 — Macro V6 Adapter (Bridges existing Macro v6 to V4 contracts)
 * ════════════════════════════════════════════════════════════════════════════════
 *  This adapter wraps the existing Macro v6 engine output into a V4
 *  ToolResultEnvelopeV4 WITHOUT modifying the Macro v6 engine and WITHOUT
 *  recalculating any result. Macro V6 remains the sole numeric authority.
 *
 *  No React, DOM, Supabase, network or file I/O.
 *  The calculationId is generated by the shared runtime adapter.
 */
import type {
  MacroInputV6,
  MacroOutputV6,
  SafetyWarningV6,
  DynamicResultV6,
} from '@/lib/tools/engines/macro.v6';
import type {
  ToolResultEnvelopeV4,
  InputSnapshot,
  InputCompleteness,
  ResultStatus,
  ProvenanceRecord,
  AssumptionRecord,
  EvidenceReference,
  UncertaintyRecord,
  SafetyWarningV4,
  ResultValidity,
  FieldState,
  Provenance,
} from './contracts.v4';
import { adaptV6ToV4Envelope } from './runtime.v4';

// ============================================================
// §1. Approved Macro → V4 state mapping (owner-authorized)
// ============================================================

/** Extended Macro state used at the V4 boundary. */
export type MacroV4State =
  | 'EMPTY'
  | 'PARTIAL'
  | 'FULL_VALID'
  | 'FULL_INVALID'
  | 'FULL_DEGRADED';

export interface MacroStateMappingV4 {
  status: ResultStatus;
  completeness: InputCompleteness;
}

/**
 * Approved mapping table:
 *
 * | Macro state   | V4 Result Status | Completeness                  |
 * |---------------|------------------|-------------------------------|
 * | EMPTY         | NOT_AVAILABLE    | INSUFFICIENT_FOR_SAFE_RESULT  |
 * | PARTIAL       | NOT_AVAILABLE    | INCOMPLETE                    |
 * | FULL valid    | VALID            | SUFFICIENT_FOR_BASIC_RESULT   |
 * | FULL invalid  | INVALID          | INCOMPLETE                    |
 * | FULL degraded | DEGRADED         | INSUFFICIENT_FOR_SAFE_RESULT  |
 */
const MACRO_STATE_MAP: Readonly<Record<MacroV4State, MacroStateMappingV4>> = {
  EMPTY: {
    status: 'NOT_AVAILABLE',
    completeness: 'INSUFFICIENT_FOR_SAFE_RESULT',
  },
  PARTIAL: {
    status: 'NOT_AVAILABLE',
    completeness: 'INCOMPLETE',
  },
  FULL_VALID: {
    status: 'VALID',
    completeness: 'SUFFICIENT_FOR_BASIC_RESULT',
  },
  FULL_INVALID: {
    status: 'INVALID',
    completeness: 'INCOMPLETE',
  },
  FULL_DEGRADED: {
    status: 'DEGRADED',
    completeness: 'INSUFFICIENT_FOR_SAFE_RESULT',
  },
};

/** Return the approved V4 status/completeness pair for a Macro state. */
export function mapMacroStateToV4(state: MacroV4State): MacroStateMappingV4 {
  return { ...MACRO_STATE_MAP[state] };
}

/**
 * Resolve the extended Macro state from the engine's dynamic completeness
 * plus the outcome of the calculation attempt.
 */
export function resolveMacroV4State(
  completeness: DynamicResultV6['completeness'],
  outcome: 'result' | 'invalid' | 'degraded' = 'result'
): MacroV4State {
  if (completeness === 'empty') return 'EMPTY';
  if (completeness === 'partial') return 'PARTIAL';
  if (outcome === 'invalid') return 'FULL_INVALID';
  if (outcome === 'degraded') return 'FULL_DEGRADED';
  return 'FULL_VALID';
}

// ============================================================
// §2. Shared envelope fragments
// ============================================================

const REQUIRED_MACRO_FIELDS = [
  'age',
  'sex',
  'heightCm',
  'weightKg',
  'activityLevel',
  'phase',
] as const;

type RequiredMacroField = (typeof REQUIRED_MACRO_FIELDS)[number];

const REQUIRED_NUMERIC_OUTPUT_FIELDS = [
  'bmr',
  'tdee',
  'targetCalories',
  'proteinGrams',
  'carbsGrams',
  'fatGrams',
  'caloriesPerKg',
  'proteinPerKg',
  'fatPerKg',
  'carbsPerKg',
] as const;

const MACRO_UNITS: Record<string, string> = {
  weight: 'kg',
  height: 'cm',
  calories: 'kcal',
  protein: 'g',
  fat: 'g',
  carbs: 'g',
};

const INVALIDATED_VALIDITY: ResultValidity = {
  status: 'INVALIDATED',
  invalidationTriggers: ['input_invalid'],
};

const NOT_ASSESSED_VALIDITY: ResultValidity = {
  status: 'NOT_ASSESSED',
  invalidationTriggers: [],
};

const CURRENT_VALIDITY: ResultValidity = {
  status: 'CURRENT',
  invalidationTriggers: ['input_changed', 'engine_version_changed'],
};

function buildFieldStates(
  input: Partial<MacroInputV6>,
  providedState: FieldState = 'VALID'
): Record<string, FieldState> {
  return Object.fromEntries(
    REQUIRED_MACRO_FIELDS.map((field) => [
      field,
      input[field] === undefined ? 'MISSING' : providedState,
    ])
  );
}

function buildProvenance(input: Partial<MacroInputV6>): Record<string, Provenance> {
  return Object.fromEntries(
    REQUIRED_MACRO_FIELDS.filter((field) => input[field] !== undefined).map(
      (field) => [field, 'USER_ENTERED' as Provenance]
    )
  );
}

function buildInputSnapshot<TInput extends Partial<MacroInputV6>>(
  input: TInput,
  state: MacroV4State,
  createdAt: string,
  providedState: FieldState = 'VALID'
): InputSnapshot<TInput> {
  return {
    values: input,
    fieldStates: buildFieldStates(input, providedState),
    provenance: buildProvenance(input),
    completeness: MACRO_STATE_MAP[state].completeness,
    recordedAt: createdAt,
    version: '4.0.0',
  };
}

function buildUserProvenance(createdAt: string): ProvenanceRecord[] {
  return [
    {
      source: 'user_input',
      recordedAt: createdAt,
      timezone: 'UTC',
      unit: 'mixed',
      confidence: null,
      dataQuality: 'not_assessed',
    },
  ];
}

function buildUnavailableUncertainty(missingFields: readonly string[]): UncertaintyRecord {
  return {
    level: 'INSUFFICIENT_EVIDENCE',
    basis: [`Missing required fields: ${missingFields.join(', ')}`],
    affectedOutputs: ['targetCalories', 'proteinGrams', 'fatGrams', 'carbsGrams'],
    whatWouldReduceIt: ['Provide all required inputs'],
    limitations: ['Cannot calculate without required inputs'],
  };
}

function buildUnavailableWarning(missingFields: readonly string[]): SafetyWarningV4 {
  return {
    warningId: 'macro-missing-inputs',
    level: 'info',
    code: 'MISSING_INPUTS',
    message: `Missing required fields: ${missingFields.join(', ')}`,
    trigger: 'missing_inputs',
    severity: 'low',
    reason: 'Required inputs have not been provided; no result was calculated.',
  };
}

function severityForWarning(level: SafetyWarningV6['level']): SafetyWarningV4['severity'] {
  switch (level) {
    case 'critical':
      return 'critical';
    case 'warning':
      return 'high';
    case 'caution':
      return 'medium';
    case 'info':
    default:
      return 'low';
  }
}

function buildDeterministicWarning(): SafetyWarningV4 {
  return {
    warningId: 'macro-deterministic-calculation',
    level: 'info',
    code: 'DETERMINISTIC_CALCULATION',
    message: 'This is a deterministic calculation, not a prediction or medical assessment.',
    trigger: 'always',
    severity: 'low',
    reason: 'Macro v6 uses documented equations; results are estimates, not measurements.',
  };
}

function buildEngineWarnings(engineWarnings: readonly SafetyWarningV6[]): SafetyWarningV4[] {
  return engineWarnings.map((warning, index) => ({
    warningId: `macro-engine-${index}-${warning.code.toLowerCase()}`,
    level: warning.level,
    code: warning.code,
    message: warning.message,
    action: warning.action,
    relatedTools: warning.relatedTools,
    trigger: 'engine_rule',
    severity: severityForWarning(warning.level),
    reason: 'Generated by the existing Macro V6 deterministic warning rules.',
  }));
}

function assertFiniteNumber(value: unknown, field: string): asserts value is number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new RangeError(`Macro V6 output field "${field}" must be a finite number.`);
  }
}

/**
 * Boundary guard only: rejects malformed or non-finite engine output.
 * It never changes a valid numeric result.
 */
export function assertValidMacroOutput(output: MacroOutputV6): void {
  if (!output || typeof output !== 'object') {
    throw new TypeError('Macro V6 output must be an object.');
  }

  for (const field of REQUIRED_NUMERIC_OUTPUT_FIELDS) {
    assertFiniteNumber(output[field], field);
  }

  if (!output.macros || typeof output.macros !== 'object') {
    throw new TypeError('Macro V6 output field "macros" must be an object.');
  }
  for (const macro of ['protein', 'carbs', 'fat'] as const) {
    const entry = output.macros[macro];
    if (!entry || typeof entry !== 'object') {
      throw new TypeError(`Macro V6 output field "macros.${macro}" must be an object.`);
    }
    assertFiniteNumber(entry.grams, `macros.${macro}.grams`);
    assertFiniteNumber(entry.calories, `macros.${macro}.calories`);
    assertFiniteNumber(entry.pct, `macros.${macro}.pct`);
  }

  if (!Array.isArray(output.assumptions) || output.assumptions.some((item) => typeof item !== 'string')) {
    throw new TypeError('Macro V6 output field "assumptions" must be an array of strings.');
  }
}

// ============================================================
// §3. Adapters
// ============================================================

/**
 * Wrap a complete, valid Macro V6 result as a V4 envelope.
 * FULL_VALID → VALID / SUFFICIENT_FOR_BASIC_RESULT.
 *
 * The result object is passed through by reference; no value is recalculated.
 */
export function adaptMacroV6ToV4(
  input: MacroInputV6,
  output: MacroOutputV6,
  createdAt: string,
  engineWarnings: readonly SafetyWarningV6[] = []
): ToolResultEnvelopeV4<MacroInputV6, MacroOutputV6> {
  assertValidMacroOutput(output);

  const state: MacroV4State = 'FULL_VALID';
  const mapping = MACRO_STATE_MAP[state];

  const assumptions: AssumptionRecord[] = output.assumptions.map((text, index) => ({
    assumptionId: `macro-assumption-${index}`,
    description: text,
    type: 'formula',
    impact: 'Result depends on this assumption.',
    version: '4.0.0',
  }));

  const evidence: EvidenceReference[] = [
    {
      evidenceId: 'mifflin-st-jeor-1990',
      sourceType: 'study',
      title:
        'Mifflin MD et al. A new predictive equation for resting energy expenditure in healthy individuals. Am J Clin Nutr. 1990;51(2):241-7.',
      url: 'https://pubmed.ncbi.nlm.nih.gov/2305711/',
      applicability:
        'Healthy adults aged 19-78; Macro permits ages 19-100 with an explicit extrapolation warning above 78.',
      limitations: [
        'Original study derived from 498 healthy adults aged 19-78.',
        'Equation estimates resting energy expenditure; it is not a measurement.',
      ],
      version: '1990',
    },
  ];

  const uncertainty: UncertaintyRecord = {
    level: 'NOT_ASSESSED',
    basis: ['No calibrated confidence model is defined for Macro v6.'],
    affectedOutputs: ['targetCalories', 'proteinGrams', 'fatGrams', 'carbsGrams'],
    whatWouldReduceIt: [
      'Direct measurement of resting metabolic rate.',
      'Validated population calibration.',
    ],
    limitations: [
      'Mifflin-St Jeor equation is an estimate, not a measurement.',
      'Activity factor is user-selected, not measured.',
    ],
  };

  const warnings: SafetyWarningV4[] = [
    buildDeterministicWarning(),
    ...buildEngineWarnings(engineWarnings),
  ];

  return adaptV6ToV4Envelope(
    'mrx.tool.macro',
    'macro',
    '6.0.0',
    mapping.status,
    buildInputSnapshot(input, state, createdAt),
    output,
    'CALCULATED',
    buildUserProvenance(createdAt),
    MACRO_UNITS,
    assumptions,
    evidence,
    uncertainty,
    warnings,
    CURRENT_VALIDITY,
    'PERSONAL',
    createdAt
  );
}

/**
 * Wrap an EMPTY or PARTIAL Macro V6 response as a V4 envelope.
 * EMPTY → NOT_AVAILABLE / INSUFFICIENT_FOR_SAFE_RESULT.
 * PARTIAL → NOT_AVAILABLE / INCOMPLETE.
 */
export function adaptMacroV6UnavailableToV4(
  input: Partial<MacroInputV6>,
  completeness: 'empty' | 'partial',
  missingFields: readonly RequiredMacroField[] | readonly string[],
  createdAt: string
): ToolResultEnvelopeV4<Partial<MacroInputV6>, null> {
  const state: MacroV4State = completeness === 'empty' ? 'EMPTY' : 'PARTIAL';
  const mapping = MACRO_STATE_MAP[state];

  return adaptV6ToV4Envelope(
    'mrx.tool.macro',
    'macro',
    '6.0.0',
    mapping.status,
    buildInputSnapshot(input, state, createdAt),
    null,
    'NOT_AVAILABLE',
    [],
    { weight: 'kg', height: 'cm' },
    [],
    [],
    buildUnavailableUncertainty(missingFields),
    [buildUnavailableWarning(missingFields)],
    NOT_ASSESSED_VALIDITY,
    'PERSONAL',
    createdAt
  );
}

/**
 * Wrap a rejected calculation as a V4 envelope.
 * FULL_INVALID → INVALID / INCOMPLETE.
 *
 * Macro V6 throws a combined validation message; no per-field attribution is
 * fabricated. Provided fields are marked INVALID at the submitted-set level.
 */
export function adaptMacroV6InvalidToV4(
  input: Partial<MacroInputV6>,
  errorMessage: string,
  createdAt: string
): ToolResultEnvelopeV4<Partial<MacroInputV6>, null> {
  const state: MacroV4State = 'FULL_INVALID';
  const mapping = MACRO_STATE_MAP[state];

  return adaptV6ToV4Envelope(
    'mrx.tool.macro',
    'macro',
    '6.0.0',
    mapping.status,
    buildInputSnapshot(input, state, createdAt, 'INVALID'),
    null,
    'NOT_AVAILABLE',
    [],
    { weight: 'kg', height: 'cm' },
    [],
    [],
    {
      level: 'HIGH',
      basis: [errorMessage],
      affectedOutputs: ['targetCalories', 'proteinGrams', 'fatGrams', 'carbsGrams'],
      whatWouldReduceIt: ['Correct the invalid input and recalculate.'],
      limitations: ['Macro V6 rejected the supplied input; no result was produced.'],
    },
    [
      {
        warningId: 'macro-invalid-input',
        level: 'warning',
        code: 'INVALID_INPUT',
        message: errorMessage,
        trigger: 'validation_failure',
        severity: 'high',
        reason: 'Macro V6 rejected the supplied input; no result was produced.',
      },
    ],
    INVALIDATED_VALIDITY,
    'PERSONAL',
    createdAt
  );
}
